#include "portModule/sendModule.h"#include <QHBoxLayout>#include <QInputDialog>#include <QLineEdit>#include <QMenu>#include <QQmlContext>#include <QQuickWidget>#include <QStandardItemModel>#include <QTableWidget>#include "globals.h"#include "portModule/basePort.h"#include "portModule/portModule.h"// publicSendModule::SendModule()    : DockWidget("Send"),      m_sendConfig(g_workspaceConfig["sendConfig"].toArray()),      m_sendWidget(new QQuickWidget()) {    setWidget(m_sendWidget);    auto *widget = new QWidget(); // NOLINT    // setWidget(widget);    auto *layout = new QVBoxLayout(widget); // NOLINT    auto *sendWidget = new QWidget(); // NOLINT    layout->addWidget(sendWidget);    auto *sendLayout = new QHBoxLayout(sendWidget); // NOLINT    sendLayout->setContentsMargins(0, 0, 0, 0);}SendModule::~SendModule() {    const auto timestamp = QDateTime::currentDateTime().toString("HH:mm:ss.zzz");    qDebug() << QString("[%1] send module destructed").arg(timestamp);}void SendModule::propertySet(const QVariantMap &objects) {    m_sendWidget->rootContext()->setContextProperty("sendModule", this);    m_sendWidget->rootContext()->setContextProperty("standardItemModel", g_portStandardItemModel);    m_sendWidget->setResizeMode(QQuickWidget::SizeRootObjectToView);    m_sendWidget->setSource(QUrl("qrc:/qml/portModule/sendModule.qml"));}void SendModule::propertyGet(const QVariantMap &objects) {    m_nameComboBox = qvariant_cast<QObject *>(objects["nameComboBox"]);    m_overrideSwitch = qvariant_cast<QObject *>(objects["overrideSwitch"]);    m_formatComboBox = qvariant_cast<QObject *>(objects["formatComboBox"]);    m_suffixComboBox = qvariant_cast<QObject *>(objects["suffixComboBox"]);    m_sendTextField = qvariant_cast<QObject *>(objects["sendTextField"]);}void SendModule::sendConfigSave() const {    g_workspaceConfig["sendConfig"] = m_sendConfig;}void SendModule::configLoad() const {    const QString portName = m_nameComboBox->property("currentText").toString();    const QJsonObject portConfig = g_port->m_portHash[portName]->config();    m_formatComboBox->setProperty("currentValue", portConfig["txFormat"].toString());    m_suffixComboBox->setProperty("currentValue", portConfig["txSuffix"].toString());}void SendModule::commandSend() const {    const QString portName = m_nameComboBox->property("currentText").toString();    QString format{};    QString suffix{};    if (m_overrideSwitch->property("checked").toBool()) {        format = m_formatComboBox->property("currentValue").toString();        suffix = m_suffixComboBox->property("currentValue").toString();    }    const QString command = m_sendTextField->property("text").toString();    const QByteArray data = command.toUtf8();    auto* port = g_port->m_portHash[portName];    bool status = false;        QMetaObject::invokeMethod(port, [&port, &data, &format, &suffix, &status] {            status = port->write(data, format, suffix);        }, Qt::BlockingQueuedConnection);    if (!status) {        qDebug() << "failed to write port: " + portName;    }}